// src/handlers/search-quickbooks-customers.handler.ts
async function searchQuickbooksCustomers(criteria = {}) {
  try {
    const quickbooks = await QuickbooksClient.getInstance();
    return new Promise((resolve) => {
      quickbooks.findCustomers(criteria, (err, customers) => {
        if (err) {
          resolve({
            result: null,
            isError: true,
            error: formatError2(err)
          });
        } else {
          resolve({
            result: customers?.QueryResponse?.Customer ?? customers?.QueryResponse?.totalCount ?? [],
            isError: false,
            error: null
          });
        }
      });
    });
  } catch (error2) {
    return {
      result: null,
      isError: true,
      error: formatError2(error2)
    };
  }
}

// src/tools/search-customers.tool.ts
var toolName12 = "search_customers";
var toolDescription12 = "Search customers in QuickBooks Online that match given criteria.";
var customerFieldEnum = external_exports.enum([
  "Id",
  "DisplayName",
  "GivenName",
  "FamilyName",
  "CompanyName",
  "PrimaryEmailAddr",
  "PrimaryPhone",
  "Balance",
  "Active",
  "MetaData.CreateTime",
  "MetaData.LastUpdatedTime"
]).describe(
  "Field to filter on \u2013 must be a property of the QuickBooks Online Customer entity."
);
var criterionSchema = external_exports.object({
  key: external_exports.string().describe("Simple key (legacy) \u2013 any Customer property name."),
  value: external_exports.union([external_exports.string(), external_exports.boolean()])
});
var advancedCriterionSchema = external_exports.object({
  field: customerFieldEnum,
  value: external_exports.union([external_exports.string(), external_exports.boolean()]),
  operator: external_exports.enum(["=", "<", ">", "<=", ">=", "LIKE", "IN"]).optional()
});
var toolSchema12 = external_exports.object({
  // Criteria can be passed as list of key/value/operator triples (array form)
  // or omitted for unfiltered search.
  criteria: external_exports.array(advancedCriterionSchema.or(criterionSchema)).optional().describe(
    "Filters to apply. Use the advanced form {field,value,operator?} for operators or the simple {key,value} pairs."
  ),
  // Pagination / sorting / count
  limit: external_exports.number().optional(),
  offset: external_exports.number().optional(),
  asc: external_exports.string().optional(),
  desc: external_exports.string().optional(),
  fetchAll: external_exports.boolean().optional(),
  count: external_exports.boolean().optional()
});
var toolHandler12 = async (args) => {
  const { criteria = [], ...options } = args.params ?? {};
  let criteriaToSend;
  if (Array.isArray(criteria) && criteria.length > 0) {
    const first2 = criteria[0];
    if (typeof first2 === "object" && "field" in first2) {
      criteriaToSend = [...criteria, ...Object.entries(options).map(([key, value]) => ({ field: key, value }))];
    } else {
      criteriaToSend = criteria.reduce((acc, { key, value }) => {
        if (value !== void 0 && value !== null) acc[key] = value;
        return acc;
      }, { ...options });
    }
  } else {
    criteriaToSend = { ...options };
  }
  const response = await searchQuickbooksCustomers(criteriaToSend);
  if (response.isError) {
    return {
      content: [{ type: "text", text: `Error searching customers: ${response.error}` }]
    };
  }
  return {
    content: [
      { type: "text", text: Array.isArray(response.result) ? `Found ${response.result.length} customers:` : `Count: ${response.result}` },
      ...Array.isArray(response.result) ? response.result.map((c) => ({ type: "text", text: JSON.stringify(c) })) : []
    ]
  };
};
var SearchCustomersTool = {
  name: toolName12,
  description: toolDescription12,
  schema: toolSchema12,
  handler: toolHandler12
};

