var toolName24 = "search_bills";
var toolDescription24 = "Search bills in QuickBooks Online that match given criteria.";
var billFieldEnum = external_exports.enum([
  "Id",
  "SyncToken",
  "MetaData.CreateTime",
  "MetaData.LastUpdatedTime",
  "TxnDate",
  "DueDate",
  "Balance",
  "TotalAmt",
  "VendorRef",
  "APAccountRef",
  "DocNumber",
  "PrivateNote",
  "ExchangeRate",
  "DepartmentRef",
  "CurrencyRef"
]).describe(
  "Field to filter on \u2013 must be a property of the QuickBooks Online Bill entity."
);
var criterionSchema4 = external_exports.object({
  key: external_exports.string().describe("Simple key (legacy) \u2013 any Bill property name."),
  value: external_exports.union([external_exports.string(), external_exports.boolean()])
});
var advancedCriterionSchema4 = external_exports.object({
  field: billFieldEnum,
  value: external_exports.union([external_exports.string(), external_exports.boolean()]),
  operator: external_exports.enum(["=", "<", ">", "<=", ">=", "LIKE", "IN"]).optional().describe("Comparison operator. Defaults to '=' if omitted.")
});
var toolSchema24 = external_exports.object({
  // Allow advanced criteria array like [{field,value,operator}]
  criteria: external_exports.array(advancedCriterionSchema4.or(criterionSchema4)).optional().describe(
    "Filters to apply. Use the advanced form {field,value,operator?} for operators or the simple {key,value} pairs."
  ),
  limit: external_exports.number().optional(),
  offset: external_exports.number().optional(),
  asc: external_exports.string().optional(),
  desc: external_exports.string().optional(),
  fetchAll: external_exports.boolean().optional(),
  count: external_exports.boolean().optional()
});
var SearchBillsTool = {
  name: toolName24,
  description: toolDescription24,
  schema: toolSchema24,
  handler: async (args) => {
    const { criteria = [], ...options } = args.params ?? {};
    let criteriaToSend;
    if (Array.isArray(criteria) && criteria.length > 0) {
      const first2 = criteria[0];
      if (typeof first2 === "object" && "field" in first2) {
        criteriaToSend = [...criteria, ...Object.entries(options).map(([key, value]) => ({ field: key, value }))];
      } else {
        criteriaToSend = criteria.reduce((acc, { key, value }) => {
          if (value !== void 0 && value !== null) acc[key] = value;
          return acc;
        }, { ...options });
      }
    } else {
      criteriaToSend = { ...options };
    }
    const response = await searchQuickbooksBills(criteriaToSend);
    if (response.isError) {
      return {
        content: [{ type: "text", text: `Error searching bills: ${response.error}` }]
      };
    }
    return {
      content: [
        { type: "text", text: Array.isArray(response.result) ? `Found ${response.result.length} bills:` : `Count: ${response.result}` },
        ...Array.isArray(response.result) ? response.result.map((b) => ({ type: "text", text: JSON.stringify(b) })) : []
      ]
    };
  }
};

