// src/handlers/search-quickbooks-purchase-orders.handler.ts
async function searchQuickbooksPurchaseOrders(data) {
  try {
    const quickbooks = await QuickbooksClient.getInstance();
    const criteria = [];
    if (data.vendor_ref) criteria.push({ field: "VendorRef", value: data.vendor_ref, operator: "=" });
    if (data.txn_date_from) criteria.push({ field: "TxnDate", value: data.txn_date_from, operator: ">=" });
    if (data.txn_date_to) criteria.push({ field: "TxnDate", value: data.txn_date_to, operator: "<=" });
    if (data.limit) criteria.push({ field: "limit", value: data.limit });
    return new Promise((resolve) => {
      quickbooks.findPurchaseOrders(criteria, (err, result2) => {
        if (err) {
          resolve({ result: null, isError: true, error: formatError2(err) });
        } else {
          const pos = result2?.QueryResponse?.PurchaseOrder || [];
          resolve({ result: pos, isError: false, error: null });
        }
      });
    });
  } catch (error2) {
    return { result: null, isError: true, error: formatError2(error2) };
  }
}

