// src/tools/search-accounts.tool.ts
var toolName30 = "search_accounts";
var toolDescription30 = "Search chart\u2011of\u2011accounts entries using criteria.";
var ALLOWED_FILTER_FIELDS2 = [
  "Id",
  "MetaData.CreateTime",
  "MetaData.LastUpdatedTime",
  "Name",
  "SubAccount",
  "ParentRef",
  "Description",
  "Active",
  "Classification",
  "AccountType",
  "CurrentBalance"
];
var ALLOWED_SORT_FIELDS2 = [
  "Id",
  "MetaData.CreateTime",
  "MetaData.LastUpdatedTime",
  "Name",
  "SubAccount",
  "ParentRef",
  "Description",
  "CurrentBalance"
];
var ACCOUNT_FIELD_TYPE_MAP = {
  Id: "string",
  "MetaData.CreateTime": "date",
  "MetaData.LastUpdatedTime": "date",
  Name: "string",
  SubAccount: "boolean",
  ParentRef: "string",
  Description: "string",
  Active: "boolean",
  Classification: "string",
  AccountType: "string",
  CurrentBalance: "number"
};
function isValidValueType(field, value) {
  const expected = ACCOUNT_FIELD_TYPE_MAP[field];
  if (!expected) return true;
  switch (expected) {
    case "string":
      return typeof value === "string";
    case "number":
      return typeof value === "number";
    case "boolean":
      return typeof value === "boolean";
    case "date":
      return typeof value === "string";
    // assume ISO date string
    default:
      return true;
  }
}
var filterableFieldSchema2 = external_exports.string().refine((val) => ALLOWED_FILTER_FIELDS2.includes(val), {
  message: `Field must be one of: ${ALLOWED_FILTER_FIELDS2.join(", ")}`
});
var sortableFieldSchema2 = external_exports.string().refine((val) => ALLOWED_SORT_FIELDS2.includes(val), {
  message: `Sort field must be one of: ${ALLOWED_SORT_FIELDS2.join(", ")}`
});
var operatorSchema2 = external_exports.enum(["=", "IN", "<", ">", "<=", ">=", "LIKE"]).optional();
var filterSchema2 = external_exports.object({
  field: filterableFieldSchema2,
  value: external_exports.any(),
  operator: operatorSchema2
}).superRefine((obj2, ctx) => {
  if (!isValidValueType(obj2.field, obj2.value)) {
    ctx.addIssue({
      code: external_exports.ZodIssueCode.custom,
      message: `Value type does not match expected type for field ${obj2.field}`
    });
  }
});
var advancedCriteriaSchema2 = external_exports.object({
  filters: external_exports.array(filterSchema2).optional(),
  asc: sortableFieldSchema2.optional(),
  desc: sortableFieldSchema2.optional(),
  limit: external_exports.number().optional(),
  offset: external_exports.number().optional(),
  count: external_exports.boolean().optional(),
  fetchAll: external_exports.boolean().optional()
});
var RUNTIME_CRITERIA_SCHEMA2 = external_exports.union([
  external_exports.record(external_exports.any()),
  external_exports.array(external_exports.record(external_exports.any())),
  advancedCriteriaSchema2
]);
function coerceAccountFieldValue(field, value) {
  const expected = ACCOUNT_FIELD_TYPE_MAP[field];
  if (!expected) return value;
  const convert = (v) => {
    switch (expected) {
      case "string":
        return typeof v === "string" ? v : String(v);
      case "number":
        return typeof v === "number" ? v : Number(v);
      case "boolean":
        return typeof v === "boolean" ? v : v === "true" || v === 1 || v === "1";
      case "date":
        return typeof v === "string" ? v : String(v);
      default:
        return v;
    }
  };
  return Array.isArray(value) ? value.map(convert) : convert(value);
}
function normalizeAccountCriteria(criteria) {
  if (!criteria) return criteria;
  if (criteria.filters && Array.isArray(criteria.filters)) {
    return {
      ...criteria,
      filters: criteria.filters.map((f) => ({
        ...f,
        value: coerceAccountFieldValue(f.field, f.value)
      }))
    };
  }
  if (Array.isArray(criteria)) {
    return criteria.map(normalizeAccountCriteria);
  }
  if (typeof criteria === "object") {
    const out = {};
    for (const [k, v] of Object.entries(criteria)) {
      out[k] = coerceAccountFieldValue(k, v);
    }
    return out;
  }
  return criteria;
}
var criteriaSchema = external_exports.any();
var toolSchema30 = external_exports.object({ criteria: criteriaSchema });
var toolHandler27 = async ({ params }) => {
  const { criteria } = params;
  const parsed = RUNTIME_CRITERIA_SCHEMA2.safeParse(criteria);
  if (!parsed.success) {
    return { content: [{ type: "text", text: `Invalid criteria: ${parsed.error.message}` }] };
  }
  const normalized = normalizeAccountCriteria(criteria);
  const response = await searchQuickbooksAccounts(normalized);
  if (response.isError) {
    return { content: [{ type: "text", text: `Error searching accounts: ${response.error}` }] };
  }
  const accounts = response.result;
  return {
    content: [
      { type: "text", text: `Found ${accounts?.length || 0} accounts:` },
      ...accounts?.map((acc) => ({ type: "text", text: JSON.stringify(acc) })) || []
    ]
  };
};
var SearchAccountsTool = {
  name: toolName30,
  description: toolDescription30,
  schema: toolSchema30,
  handler: toolHandler27
};

